SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, SUM(CASE WHEN s.device = 'mobile' THEN 1 ELSE 0 END) AS mobile_count, COUNT(*) AS total_count FROM sessions s JOIN customers c ON s.customer_id = c.id WHERE s.country NOT IN ('SG', 'JP') GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY signup_cohort DESC;
